        "index.html": Asset(contentType: "text/html; charset=utf-8", body: #"""
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no, viewport-fit=cover">
  <meta name="color-scheme" content="dark">
  <title>Overscreen</title>
  <link rel="stylesheet" href="style.css">
</head>
<body>
  <main id="setup" class="setup">
    <header class="brand">
      <div class="logo" aria-hidden="true"></div>
      <div>
        <h1>Overscreen</h1>
        <p id="host-name" class="muted">Connecting…</p>
      </div>
    </header>

    <p id="insecure" class="warning" role="alert" hidden>This connection is not encrypted. Others on this network could watch or take over the session.</p>

    <section id="pair" class="card" hidden>
      <h2>Enter pairing code</h2>
      <p class="muted">The code is shown in the Overscreen menu on your Mac.</p>
      <div id="code-display" class="code" aria-live="polite"></div>
      <div id="keypad" class="keypad"></div>
      <p id="pair-error" class="error" role="alert"></p>
    </section>

    <section id="pick" class="card" hidden>
      <h2>Choose a display</h2>
      <div id="display-list" class="display-list"></div>
      <button id="forget" class="link" type="button">Forget this device</button>
    </section>

    <p id="setup-error" class="error" role="alert"></p>
  </main>

  <div id="stage" class="stage" hidden>
    <video id="video" autoplay playsinline muted disablepictureinpicture disableremoteplayback></video>
    <div id="overlay" class="overlay">
      <div class="spinner" aria-hidden="true"></div>
      <p id="overlay-text">Starting…</p>
      <button id="overlay-action" type="button" hidden></button>
    </div>
    <button id="handle" class="handle" type="button" aria-label="Menu"></button>
    <nav id="menu" class="menu" hidden>
      <button id="menu-fullscreen" type="button">Full screen</button>
      <button id="menu-stats" type="button">Show stats</button>
      <button id="menu-disconnect" type="button">Disconnect</button>
    </nav>
    <pre id="hud" class="hud" hidden></pre>
  </div>

  <script src="gestures.js"></script>
  <script src="client.js"></script>
</body>
</html>
"""#),
        "style.css": Asset(contentType: "text/css; charset=utf-8", body: #"""
:root {
  --bg: #0d1014;
  --card: #171b21;
  --line: #2a313b;
  --text: #e8edf2;
  --muted: #8b96a3;
  --accent: #4f9cff;
  --danger: #ff6b6b;
  --warning: #ffb547;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  height: 100%;
  background: var(--bg);
  color: var(--text);
  font: 16px/1.4 -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  -webkit-tap-highlight-color: transparent;
  -webkit-user-select: none;
  user-select: none;
}

[hidden] { display: none !important; }

.setup {
  max-width: 560px;
  margin: 0 auto;
  padding: 32px 16px;
}

.brand { display: flex; gap: 16px; align-items: center; margin-bottom: 24px; }
.brand h1 { margin: 0; font-size: 28px; }
.brand p { margin: 2px 0 0; }
.logo {
  width: 48px; height: 48px; border-radius: 12px;
  background: linear-gradient(135deg, var(--accent), #8a5cff);
}

.card {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 16px;
  padding: 20px;
}
.card h2 { margin: 0 0 4px; font-size: 20px; }

.muted { color: var(--muted); }
.error { color: var(--danger); min-height: 1.4em; }
.warning { color: var(--warning); border: 1px solid var(--warning); border-radius: 10px; padding: 10px 12px; }

.code {
  margin: 20px 0;
  text-align: center;
  font: 600 40px/1 ui-monospace, Menlo, monospace;
  letter-spacing: 12px;
  min-height: 40px;
}

.keypad { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; }
.keypad button, .display-list button, .overlay button {
  min-height: 64px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: #202631;
  color: var(--text);
  font-size: 24px;
}
.keypad button:active, .display-list button:active { background: #2b3442; }

.display-list { display: grid; gap: 10px; margin: 16px 0; }
.display-list button { font-size: 20px; text-align: left; padding: 0 20px; display: flex; justify-content: space-between; align-items: center; }
.display-list .tag { font-size: 14px; color: var(--muted); }

.link { background: none; border: 0; color: var(--accent); font-size: 15px; padding: 8px 0; }

.stage {
  position: fixed;
  inset: 0;
  background: #000;
  touch-action: none;
  overflow: hidden;
}

/* A single promoted layer keeps weak in-car compositors from repainting around the video. */
video {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: contain;
  background: #000;
  transform: translateZ(0);
  pointer-events: none;
}

.overlay {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 16px;
  background: rgba(0, 0, 0, 0.85);
  font-size: 20px;
  text-align: center;
  padding: 16px;
}
.overlay button { padding: 0 28px; font-size: 20px; }
#overlay-text { white-space: pre-line; max-width: 36em; margin: 0; }

.spinner {
  width: 40px; height: 40px;
  border: 4px solid var(--line);
  border-top-color: var(--accent);
  border-radius: 50%;
  animation: spin 1s linear infinite;
}
.overlay.idle .spinner { display: none; }
@keyframes spin { to { transform: rotate(360deg); } }

.handle {
  position: absolute;
  top: 0; left: 50%;
  width: 72px; height: 18px;
  margin-left: -36px;
  border: 0;
  border-radius: 0 0 10px 10px;
  background: rgba(255, 255, 255, 0.18);
}

.menu {
  position: absolute;
  top: 24px; left: 50%;
  transform: translateX(-50%);
  display: flex;
  gap: 8px;
  padding: 8px;
  background: rgba(23, 27, 33, 0.95);
  border: 1px solid var(--line);
  border-radius: 12px;
}
.menu button {
  min-height: 48px;
  padding: 0 16px;
  border: 0;
  border-radius: 8px;
  background: #202631;
  color: var(--text);
  font-size: 16px;
}

.hud {
  position: absolute;
  left: 8px; bottom: 8px;
  margin: 0;
  padding: 6px 8px;
  background: rgba(0, 0, 0, 0.6);
  border-radius: 6px;
  font: 12px/1.3 ui-monospace, Menlo, monospace;
  pointer-events: none;
}
"""#),
